<?php require_once '../config/config.php';if(!empty($_SESSION['admin_id'])){header('Location:index.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){ $q=db()->prepare("SELECT * FROM admins WHERE username=?");$q->execute([$_POST['username']??'']);$a=$q->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){$_SESSION['admin_id']=$a['id'];header('Location:index.php');exit;}$error='اسم المستخدم أو كلمة المرور غير صحيحة';}?>
